// Copies the OpenAPI types generated by the backend (`npm run openapi` in backend/) into the frontend, so there is one
// source of truth and no hand-written duplicate of the wire types.
//   npm run api:types          copy backend/openapi/schema.d.ts -> src/api/schema.d.ts
//   npm run api:types:check    exit 1 when the copy is out of date (used by a test and CI)
import { copyFileSync, existsSync, readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, "../../backend/openapi/schema.d.ts");
const target = resolve(here, "../src/api/schema.d.ts");

if (!existsSync(source)) {
  console.error(`Cannot find ${source}. Run "npm run openapi" in backend/ first.`);
  process.exit(1);
}
if (process.argv.includes("--check")) {
  const same = existsSync(target) && readFileSync(source, "utf8") === readFileSync(target, "utf8");
  if (!same) {
    console.error("src/api/schema.d.ts is out of date. Run: npm run api:types");
    process.exit(1);
  }
  console.log("api types: up to date");
} else {
  copyFileSync(source, target);
  console.log("api types: copied backend/openapi/schema.d.ts -> src/api/schema.d.ts");
}
